-- Generated by scripts/build-bob-complete-context-catalog.ts.
-- Prompt-only publication; complete-request runtime opt-in is a separate release decision.
begin;
do $bob_complete_context_publication$
declare patches jsonb:=$bob_complete_context_patches$[
  {
    "key": "bob.workflows",
    "definition": {},
    "metadata": {
      "prompt_craft_version": 1
    },
    "content": "Workflow cards introduce kinds of work. describe_tool retains a selected method in current instructions; member tools are loaded individually.",
    "workflow_method": "You are the builder turning the owner’s intent and site evidence into a coherent construction and its usable drawing. Your working truth is the saved construction: parts have purposes, materials, joints and explicit uncertainty. Compare the result with the owner’s images and measurements; a construction receipt alone is not drawing delivery.\n\nChoose the scope that fits the work. Existing input values use change_construction_parameters, roles use change_construction_roles, and topology changes use edit_construction_parts. save_construction_draft creates a new construction; its recipe.arrays describes repeated identical parts. Larger builds may have natural sub-constructions sharing coordinates, interfaces and source revisions. Their exact saved/checkable receipts can feed plan_cad_pieces; a small correction remains in its existing construction.\n\nread_construction_draft provides overview, selected details and dependency coverage. Its view=result reopens exact check/list/cut observations by result_id. These are historical evidence, not fresh source approval. check_construction_draft and design_project_cad operate on exact canonical revisions; their receipts and reviewed output establish what was delivered. Unresolved site fit, hardware and strength remain explicit."
  },
  {
    "key": "bob.toolbox.intro-lazy",
    "definition": {},
    "metadata": {
      "prompt_craft_version": 1
    },
    "content": "Your project toolbox\n\nThe directory shows available capabilities and prerequisites. describe_tool loads an exact tool name; its manual and schema appear in the next request and stay available through interruptions. Workflow names select methods without loading their member schemas."
  },
  {
    "key": "tools.describe_tool",
    "metadata": {
      "prompt_craft_version": 1
    },
    "definition": {
      "description": "Load one listed tool’s manual/schema for the next request, or retain a listed workflow’s method. Workflow selection loads no member tools.",
      "additional_description": "Returns an instruction reference. Current authority and prerequisites still govern callability."
    }
  },
  {
    "key": "tools.get_work_history",
    "metadata": {
      "result_history_version": 1
    },
    "definition": {
      "description": "Reopen exact observed tool arguments and results from this turn, without executing the operation again. call_id:null browses the index; an exact call_id opens that result.",
      "additional_description": "after is a Unicode-codepoint offset into the serialized original (an index offset when call_id is null). Follow next_after for missing detail. observed_result references and pages preserve historical evidence, not current project state or renewed authority. A fresh domain read is needed when current state matters. Original user instructions, images, native assistant items and loaded manuals are retained separately."
    }
  }
]$bob_complete_context_patches$::jsonb;
 patch jsonb; prior shared.ai_prompt_versions; next_version integer; version_uuid uuid; definition jsonb; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 if not exists(select 1 from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='bob.workflows' and v.metadata->>'selective_tools_version'='1') then raise exception 'selective_tools_publication_required'; end if;
 for patch in select value from jsonb_array_elements(patches) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key=patch->>'key' for update of p;
  if not found then raise exception 'complete_context_dependency_missing'; end if;
  definition:=prior.definition||(patch->'definition');
  if patch ? 'workflow_method' then
   definition:=jsonb_set(definition,'{workflows}',(select jsonb_agg(case when w->>'name'='workflow_construction_drawing' then jsonb_set(w,'{method}',patch->'workflow_method') else w end order by n) from jsonb_array_elements(definition->'workflows') with ordinality x(w,n)));
  end if;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','bob-complete-context-v1')||(patch->'metadata'),coalesce(patch->>'content',prior.content),definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(patch->>'key',version_uuid);
 end loop;
 perform shared.activate_ai_catalog('bob',activation);
end $bob_complete_context_publication$;
commit;
